function drawTile(x, y, w, res) {
	let ww = w / res;
	noStroke();
	for (let i = 0; i < res; i++) {
		for (let j = 0; j < res; j++) {
			let xx = i * ww + (ww / 2) + x - (w / 2);
			let yy = j * ww + (ww / 2) + y - (w / 2);
			const tileColor = random(palette);
			fill(tileColor);
			rect(xx, yy, ww * 0.75);
			drawMirroredMaskGrid(xx, yy, ww * 0.5, tileColor);
		}
	}
}

function buildCenteredMirrorArray(baseGrid) {
	const rowCount = baseGrid.length;
	const colCount = baseGrid[0].length;
	const mirroredGrid = [];

	for (let row = 0; row < rowCount * 2; row++) {
		const sourceRow = row < rowCount ? row : rowCount * 2 - 1 - row;
		mirroredGrid[row] = [];
		for (let col = 0; col < colCount * 2; col++) {
			const sourceCol = col < colCount ? col : colCount * 2 - 1 - col;
			const sourceCell = baseGrid[sourceRow][sourceCol];
			mirroredGrid[row][col] =
				sourceCell !== null && typeof sourceCell === 'object'
					? { ...sourceCell }
					: sourceCell;
		}
	}

	return mirroredGrid;
}

function createRandomTypeGrid(gridSize, typeCount, colorPool) {
	return Array.from({ length: gridSize }, () =>
		Array.from({ length: gridSize }, () => ({
			shapeType: int(random(typeCount)),
			angle: int(random(4)) * (TAU / 4),
			color: random(colorPool)
		}))
	);
}

function drawMirroredMaskGrid(centerX, centerY, gridWidth, excludedColor) {
	const baseGridSize = 2;
	const mirroredGridSize = baseGridSize * 2;
	const cellSize = gridWidth / mirroredGridSize;
	const availableMaskColors = palette.filter(color => color !== excludedColor);
	const colorPool = availableMaskColors.length > 0 ? availableMaskColors : palette;
	const baseGrid = createRandomTypeGrid(baseGridSize, 6, colorPool);

	const mirroredGrid = buildCenteredMirrorArray(baseGrid);
	push();
	translate(centerX - (gridWidth / 2), centerY - (gridWidth / 2));

	for (let row = 0; row < mirroredGridSize; row++) {
		for (let col = 0; col < mirroredGridSize; col++) {
			const cellCenterX = (row * cellSize) + (cellSize / 2);
			const cellCenterY = (col * cellSize) + (cellSize / 2);
			const cellData = mirroredGrid[row][col];
			let scaleX = 1;
			let scaleY = 1;
			if (row >= (mirroredGridSize / 2)) {
				scaleX = -1;
			}
			if (col >= (mirroredGridSize / 2)) {
				scaleY = -1;
			}
			drawMaskCell(
				cellCenterX,
				cellCenterY,
				cellSize,
				cellData.shapeType,
				cellData.angle,
				cellData.color,
				scaleX,
				scaleY
			);
		}
	}
	pop();
}

function drawMaskCell(x, y, w, shapeType, angle, fillColor, scaleX, scaleY) {
	push();
	translate(x, y);
	scale(scaleX, scaleY);
	rotate(angle);
	fill(fillColor);
	noStroke();
	if (shapeType == 0) {
		beginShape();
		vertex(-w / 2, -w / 2);
		vertex(w / 2, w / 2);
		vertex(-w / 2, w / 2);
		endShape();
	}
	else if (shapeType === 1) {
		arc(-w / 2, -w / 2, w * 2, w * 2, 0, HALF_PI);
	}
	else if (shapeType === 2) {

		arc(0, -w / 2, w, w, 0, PI);
	}
	else if (shapeType === 3) {
		square(0, 0, w);
	}
	else if (shapeType === 4) {
		rect(0, -w * 0.25, w, w * 0.5);
	}
	else if (shapeType === 5) {
		beginShape();
		vertex(0, -w / 2);
		vertex(w / 2, 0);
		vertex(0, w / 2);
		vertex(-w / 2, 0);
		endShape();
	}
	pop();
}


